#!/usr/bin/env bash
#
# Pixie SDDM - Desktop wallpaper synchronization + Matugen dynamic theming
#
# Change your desktop wallpaper once, and Pixie SDDM picks it up (plus a
# matching Material You palette generated by Matugen) the next time the
# login screen is shown.
#
# Usage:
#   update-wallpaper.sh [OPTIONS] [WALLPAPER_PATH]
#
# Options:
#   -m, --mode <dark|light>    Matugen color scheme mode (default: dark).
#                              Auto-detection is used when no wallpaper path
#                              is given.
#   -f, --force                Regenerate even if the wallpaper did not change.
#   -d, --disable              Disable sync: clear the "wallpaper" key and turn
#                              off the generated palette. theme.conf defaults
#                              (background/autoColor/accentColor) apply again.
#   -t, --theme-dir <dir>      SDDM theme directory
#                              (default: /usr/share/sddm/themes/pixie).
#       --assets-dir <dir>     Shared, world-readable wallpaper/palette dir
#                              (default: /var/lib/sddm/pixie).
#   -n, --dry-run              Run the full workflow but change nothing.
#   -h, --help                 Show this help.
#
# Environment (all optional):
#   PIXIE_WALLPAPER   Preset wallpaper path (same as the positional argument).
#   PIXIE_THEME_DIR   Theme installation directory.
#   PIXIE_ASSETS_DIR  Shared assets directory.
#   PIXIE_MODE        "dark" or "light" (same as --mode).
#   PIXIE_SCHEME      Matugen scheme type (default: scheme-tonal-spot,
#                     see `matugen image --help` for all values).
#   PIXIE_DISABLE_MATUGEN=1  Copy the wallpaper but skip palette generation.
#
# Exit codes: 0 = success (or no change), 1 = failure, 2 = usage error.
#
# SECURITY NOTES
#   * Copying the wallpaper into the shared assets dir and updating theme.conf
#     touch root-owned directories (/var/lib/sddm, /usr/share/sddm), so the
#     script re-execs itself once via `sudo -E` when its writes would
#     otherwise fail. Wallpaper detection always runs as your user.
#   * Only the wallpaper copy and the assets directory metadata are modified.
#     No recursive chmod, nothing from your home is exposed except a copy of
#     the wallpaper itself.
#   * To avoid sudo on repeated runs, hand the shared dir to your user once:
#       sudo install -d -o "$USER" -m 755 /var/lib/sddm/pixie
#     (theme.conf updates still require privileges in stock installs).

set -u -o pipefail

# ----------------------------------------------------------------------------
# Layout / defaults
# ----------------------------------------------------------------------------
SELF="$(cd -- "$(dirname -- "${BASH_SOURCE[0]}")" >/dev/null 2>&1 && pwd -P)/$(basename -- "${BASH_SOURCE[0]}")"

THEME_DIR="${PIXIE_THEME_DIR:-/usr/share/sddm/themes/pixie}"
ASSETS_DIR="${PIXIE_ASSETS_DIR:-/var/lib/sddm/pixie}"
MODE="${PIXIE_MODE:-dark}"
SCHEME="${PIXIE_SCHEME:-scheme-tonal-spot}"

RED='\033[0;31m'; GREEN='\033[0;32m'; BLUE='\033[0;34m'; YELLOW='\033[0;33m'; NC='\033[0m'
msg()  { printf "${BLUE}==>${NC} %s\n" "$*"; }
ok()   { printf "${GREEN}==>${NC} %s\n" "$*"; }
warn() { printf "${YELLOW}==>${NC} %s\n" "$*" >&2; }
die()  { printf "${RED}Error:${NC} %s\n" "$*" >&2; exit 1; }

usage() { sed -n '2,32p' "$SELF"; }

FORCE=0
DISABLE=0
DRY_RUN=0
DETECTED=""
WALLPAPER="${PIXIE_WALLPAPER:-}"

while [ $# -gt 0 ]; do
    case "$1" in
        -m|--mode)        [ $# -ge 2 ] || { usage >&2; die "--mode requires an argument"; } ; MODE="${2}"; shift ;;
        -f|--force)       FORCE=1 ;;
        -d|--disable)     DISABLE=1 ;;
        -n|--dry-run)     DRY_RUN=1 ;;
        -t|--theme-dir)   [ $# -ge 2 ] || { usage >&2; die "--theme-dir requires an argument"; } ; THEME_DIR="${2}"; shift ;;
        --assets-dir)     [ $# -ge 2 ] || { usage >&2; die "--assets-dir requires an argument"; } ; ASSETS_DIR="${2}"; shift ;;
        -h|--help)        usage; exit 0 ;;
        -*)               usage >&2; die "Unknown option: $1" ;;
        *) if [ -n "$WALLPAPER" ]; then usage >&2; die "Multiple wallpaper paths given."; fi
           WALLPAPER="$1" ;;
    esac
    shift
done

[ -n "${PIXIE_FORCE:-}" ] && FORCE=1
if [ "$DISABLE" -eq 1 ]; then WALLPAPER=""; fi

case "$MODE" in dark|light) ;; *) usage >&2; die "--mode must be 'dark' or 'light'." ;; esac

MATUGEN_TEMPLATE="${THEME_DIR}/scripts/matugen/pixie-${MODE}.conf"
THEME_CONF="${THEME_DIR}/theme.conf"
USER_HOOK="${XDG_CONFIG_HOME:-$HOME/.config}/pixie-sddm/get-wallpaper.sh"

# ----------------------------------------------------------------------------
# Wallpaper detection (best effort, first hit wins; runs as the *user*)
# Extend by installing your own hook that prints one path:
#   ~/.config/pixie-sddm/get-wallpaper.sh
# ----------------------------------------------------------------------------
strip_uri() {
    # "'file:///path with space.jpg'" -> "/path with space.jpg"
    local p="$1"
    p="$(printf '%s' "$p" | sed -e "s/^'//; s/'\$//")"
    p="$(printf '%s' "$p" | sed -e 's/^"//; s/"$//')"
    p="${p#file://}"
    printf '%s' "$p"
}

detect_quickshell() {
    local f="${XDG_STATE_HOME:-$HOME/.local/state}/quickshell/user/generated/wallpaper/path.txt"
    [ -s "$f" ] || return 1
    local p; p="$(tr -d '\r\n' < "$f")"
    [ -n "$p" ] && [ -f "$p" ] && { printf '%s' "$p"; return 0; }
    return 1
}

detect_gsettings() {
    command -v gsettings >/dev/null 2>&1 || return 1
    local schema key uri
    local keys_dark="picture-uri-dark picture-uri"
    local keys_light="picture-uri picture-uri-dark"
    local keys_all keys
    keys_all="$keys_light"
    [ "$MODE" = "dark" ] && keys_all="$keys_dark"
    for schema in org.gnome.desktop.background \
                  org.cinnamon.desktop.background \
                  org.mate.background; do
        gsettings list-schemas 2>/dev/null | grep -qx "$schema" || continue
        for key in $keys_all; do
            uri="$(gsettings get "$schema" "$key" 2>/dev/null)" || uri=""
            case "$uri" in
                file://*|"'"*"'"|'"'*'"') ;;
                *) continue ;;
            esac
            uri="$(strip_uri "$uri")"
            [ -n "$uri" ] && [ -f "$uri" ] && { printf '%s' "$uri"; return 0; }
        done
    done
    return 1
}

detect_hyprpaper() {
    # Requires an active Hyprland session (HYPRLAND_INSTANCE_SIGNATURE)
    command -v hyprctl >/dev/null 2>&1 || return 1
    [ -n "${HYPRLAND_INSTANCE_SIGNATURE:-}" ] || return 0
    local out p
    out="$(hyprctl hyprpaper listactive 2>/dev/null)" || return 1
    p="$(printf '%s\n' "$out" | awk -F': ' '/^.*: /{print $2}' | tail -n1)"
    [ -n "$p" ] && [ -f "$p" ] && { printf '%s' "$p"; return 0; }
    return 1
}

detect_swww() {
    command -v swww >/dev/null 2>&1 || return 1
    local line p
    line="$(swww query 2>/dev/null | head -n1)" || return 1
    p="${line#*: }"
    [ -n "$p" ] && [ "$p" != "$line" ] && [ -f "$p" ] && { printf '%s' "$p"; return 0; }
    return 1
}

detect_plasma() {
    local f="${XDG_CONFIG_HOME:-$HOME/.config}/plasma-org.kde.plasma.desktop-appletsrc"
    [ -f "$f" ] || return 1
    local p
    p="$(grep -E '^Image=' "$f" | tail -n1 | cut -d= -f2-)"
    [ -n "$p" ] || return 1
    p="$(strip_uri "$p")"
    [ -f "$p" ] && { printf '%s' "$p"; return 0; }
    return 1
}

detect_nitrogen() {
    local f="${XDG_CONFIG_HOME:-$HOME/.config}/nitrogen/bg-saved.cfg"
    [ -f "$f" ] || return 1
    local p
    p="$(grep '^file=' "$f" | tail -n1 | cut -d= -f2-)"
    [ -n "$p" ] && [ -f "$p" ] && { printf '%s' "$p"; return 0; }
    return 1
}

detect_feh() {
    local f="$HOME/.fehbg"
    [ -f "$f" ] || return 1
    local p
    # feh writes: sh -c 'feh --bg-fill "file:///path" --no-xinerama' or similar
    p="$(grep -oP '(--bg-\w+ +)\K("[^"]+"|\S+)' "$f" 2>/dev/null | head -n1)" || p=""
    p="$(strip_uri "$p")"
    p="${p%\'}"; p="${p%\"}"
    p="${p#file://}"
    [ -n "$p" ] && [ -f "$p" ] && { printf '%s' "$p"; return 0; }
    return 1
}

detect_xfce() {
    command -v xfconf-query >/dev/null 2>&1 || return 1
    local p
    p="$(xfconf-query -c xfce4-desktop -l -v 2>/dev/null \
        | awk '$1 ~ /last-image/ { $1=""; sub(/^ +/, ""); printf "%s", $0; exit }')"
    [ -n "$p" ] || return 1
    p="$(strip_uri "$p")"
    [ -f "$p" ] && { printf '%s' "$p"; return 0; }
    return 1
}

detect_hook() {
    [ -x "$USER_HOOK" ] || return 1
    local p
    p="$("$USER_HOOK" 2>/dev/null | head -n1)" || return 1
    [ -n "$p" ] && [ -f "$p" ] && { printf '%s' "$p"; return 0; }
    return 1
}

detect_wallpaper() {
    local detector
    for detector in hook quickshell hyprpaper swww gsettings plasma nitrogen feh xfce; do
        local p
        p="$("detect_${detector}" 2>/dev/null)" || p=""
        if [ -n "$p" ]; then
            msg "Detected wallpaper via ${detector}: $p"
            DETECTED="$p"
            return 0
        fi
    done
    DETECTED=""
    return 1
}

# ----------------------------------------------------------------------------
# Validation
# ----------------------------------------------------------------------------
is_image() {
    local f="$1"
    if command -v file >/dev/null 2>&1; then
        file -b --mime-type "$f" 2>/dev/null | grep -qi '^image/'
        return $?
    elif command -v identify >/dev/null 2>&1; then
        identify -quiet "$f" >/dev/null 2>&1
        return $?
    fi
    # Fallback: extension check against the formats QML supports everywhere
    case "${f,,}" in
        *.jpg|*.jpeg|*.png|*.bmp|*.gif|*.webp) return 0 ;;
        *) return 1 ;;
    esac
}

sha_of() { sha256sum -- "$1" 2>/dev/null | awk '{print $1}'; }

# ----------------------------------------------------------------------------
# theme.conf key handling
# ----------------------------------------------------------------------------
ini_escape() { printf '%s' "$1" | sed -e 's/[\\\\|&]/\\\\&/g'; }

set_key() {   # set_key FILE KEY [VALUE]   (in place, appends when missing)
    local file="$1" key="$2" val="${3-}"
    if grep -q "^${key}=" "$file"; then
        sed -i "s|^${key}=.*|${key}=$(ini_escape "$val")|" "$file"
    else
        printf '%s=%s\n' "$key" "$val" >> "$file"
    fi
}

get_key() { grep -m1 "^${2}=" "$1" 2>/dev/null | cut -d= -f2- ; }

# ----------------------------------------------------------------------------
# Privilege handling - sudo re-exec only if our writes would fail
# ----------------------------------------------------------------------------
needs_privileges() {
    [ "$(id -u)" -eq 0 ] && return 1
    if [ -d "$ASSETS_DIR" ]; then
        [ -w "$ASSETS_DIR" ] || return 0
    else
        [ -d "$(dirname "$ASSETS_DIR")" ] && [ -w "$(dirname "$ASSETS_DIR")" ] || return 0
    fi
    [ -w "$THEME_CONF" ] || return 0
    return 1
}

escalate() {
    # Re-exec as root with the validated path and reproduced options.
    [ -x "$(command -v sudo)" ] || return 1
    local exe=(env PATH="$PATH"
               PIXIE_THEME_DIR="$THEME_DIR" PIXIE_ASSETS_DIR="$ASSETS_DIR"
               PIXIE_MODE="$MODE" PIXIE_SCHEME="$SCHEME" PIXIE_FORCE="$FORCE")
    msg "Writing needs root access - retrying via sudo..."
    if [ -t 0 ]; then
        exec sudo -E "${exe[@]}" -- "$SELF" $([ "$DISABLE" -eq 1 ] && echo --disable) "$WALLPAPER"
    fi
    return 1
}

# ----------------------------------------------------------------------------
# Matugen generation
# ----------------------------------------------------------------------------
generate_palette() {      # generate_palette IMAGE_PATH -> prints fragment path (or fails)
    local img="$1"
    command -v matugen >/dev/null 2>&1 || { warn "Matugen not installed - wallpaper synced, previous palette kept."; return 1; }
    [ -f "$MATUGEN_TEMPLATE" ] || { warn "Matugen template missing ($MATUGEN_TEMPLATE) - palette unchanged."; return 1; }

    local tmpcfg tmpproc
    tmpcfg="$(mktemp)" || return 1
    tmpproc="$(mktemp)" || { rm -f "$tmpcfg"; return 1; }

    cat > "$tmpcfg" <<EOF
[config]
version_check = false

[templates.pixie]
input_path = '$MATUGEN_TEMPLATE'
output_path = '$tmpproc'
EOF

    local matugen_log="$tmpproc.log"
    if ! matugen image "$img" -c "$tmpcfg" -t "$SCHEME" -m "${MODE:-dark}" \
         --source-color-index "${PIXIE_SOURCE_COLOR_INDEX:-0}" >"$matugen_log" 2>&1; then
        warn "Matugen failed - keeping the previous palette."
        [ "${PIXIE_DEBUG:-0}" = "1" ] && sed 's/^/  | /' "$matugen_log" >&2
        rm -f "$tmpcfg" "$tmpproc" "$matugen_log"
        return 1
    fi
    rm -f "$tmpcfg" "$matugen_log"

    if ! grep -qx 'matugen=true' "$tmpproc" \
      || ! grep -qE '^matugenAccent=#[0-9a-fA-F]{6}$' "$tmpproc" \
      || ! grep -qE '^matugenBackground=#[0-9a-fA-F]{6}$' "$tmpproc" \
      || ! grep -qE '^matugenText=#[0-9a-fA-F]{6}$' "$tmpproc"; then
        warn "Matugen output failed validation - keeping the previous palette."
        rm -f "$tmpproc"
        return 1
    fi

    printf '%s' "$tmpproc"
}

commit_palette() {   # commit_palette FRAGMENT THEME_CONF
    local frag="$1" conf="$2" key val
    while IFS='=' read -r key val; do
        case "$key" in
            matugen|matugenAccent|matugenBackground|matugenText) set_key "$conf" "$key" "$val" ;;
        esac
    done < "$frag"
    rm -f "$frag"
}

# Simple dry-run renderer check
try_matugen_dryrun() { # prints nothing, returns 0 if matugen would work
    local img="$1" frag rc
    frag="$(generate_palette "$img")" ; rc=$?
    [ -n "$frag" ] && rm -f "$frag"
    return $rc
}

# ----------------------------------------------------------------------------
# Main workflow
# ----------------------------------------------------------------------------
main() {
    echo "Pixie SDDM wallpaper sync (mode: $MODE, dry-run: $([ "$DRY_RUN" = 1 ] && echo yes || echo no))"

    [ -d "$THEME_DIR" ] || die "Theme directory not found: $THEME_DIR (use --theme-dir)"
    [ -f "$THEME_CONF" ] || die "theme.conf not found in $THEME_DIR"

    # ---- Resolve wallpaper path first (runs as the user, DE tools work) ----
    if [ "$DISABLE" -ne 1 ]; then
        if [ -z "$WALLPAPER" ]; then
            msg "No wallpaper path given - detecting the current desktop wallpaper..."
            detect_wallpaper || true
            WALLPAPER="$DETECTED"
        fi
        [ -n "$WALLPAPER" ] || die "No wallpaper provided or detected. Pass a path, set PIXIE_WALLPAPER, or install your own ~/.config/pixie-sddm/get-wallpaper.sh hook."

        # ---- Validate ----
        [ -f "$WALLPAPER" ] || die "Wallpaper not found: $WALLPAPER"
        [ -r "$WALLPAPER" ] || die "Wallpaper not readable: $WALLPAPER"
        [ "$(wc -c <"$WALLPAPER")" -gt 0 ] || die "Wallpaper is empty: $WALLPAPER"
        is_image "$WALLPAPER" || die "Unsupported or invalid image file: $WALLPAPER"
    fi

    # ---- Escalate only if the mutating steps would fail ----
    if [ "$DRY_RUN" = 0 ] && needs_privileges; then
        if ! escalate; then
            die "Could not obtain write access. Rerun with:  sudo -E $SELF $*"
        fi
        exit 0  # escalate() execs - this line is only hit if sudo is missing
    fi

    # ---- Disable mode ----
    if [ "$DISABLE" -eq 1 ]; then
        if [ "$DRY_RUN" = 1 ]; then
            msg "Dry run: would clear 'wallpaper=' and set 'matugen=false' in $THEME_CONF"
            exit 0
        fi
        msg "Disabling wallpaper sync and the generated palette..."
        set_key "$THEME_CONF" "wallpaper" ""
        set_key "$THEME_CONF" "matugen" "false"
        rm -f "$ASSETS_DIR/.last-wallpaper" "$ASSETS_DIR/.last-sha" 2>/dev/null || true
        ok "Sync disabled. Pixie now uses the background/autoColor/accentColor defaults from theme.conf."
        exit 0
    fi

    # ---- Dry run stops here ----
    if [ "$DRY_RUN" = 1 ]; then
        msg "Dry run: would install '$WALLPAPER' into $ASSETS_DIR and update $THEME_CONF."
        if command -v matugen >/dev/null 2>&1; then
            if try_matugen_dryrun "$WALLPAPER"; then
                ok "Dry run: Matugen palette generation works."
            else
                warn "Dry run: Matugen palette generation FAILED."
            fi
        else
            warn "Dry run: Matugen is not installed (palette step would be skipped)."
        fi
        exit 0
    fi

    # ---- Shared assets dir ----
    if [ ! -d "$ASSETS_DIR" ]; then
        echo "==> Creating shared assets dir at $ASSETS_DIR"
        mkdir -p -- "$ASSETS_DIR" || die "Cannot create $ASSETS_DIR"
    fi
    chmod 0755 "$ASSETS_DIR" || die "Cannot chmod $ASSETS_DIR"

    # ---- Rerun safety: skip when the wallpaper content did not change ----
    WALLSHA="$(sha_of "$WALLPAPER")"
    if [ "$FORCE" -ne 1 ] && [ -f "$ASSETS_DIR/.last-sha" ]; then
        if [ "$(cat "$ASSETS_DIR/.last-sha" 2>/dev/null)" = "$WALLSHA" ]; then
            ok "Wallpaper unchanged (same content) - nothing to do. Use --force to re-run."
            exit 0
        fi
    fi

    # ---- Install the wallpaper into the shared dir ----
    local ext="${WALLPAPER##*.}"
    ext="$(printf '%s' "${ext,,}" | tr -cd 'a-z0-9')"
    case "$ext" in
        jpg|jpeg|png|bmp|gif|webp|svg) ;;
        *) warn "Unusual extension '.$ext' - defaulting to .png"; ext="png" ;;
    esac
    local DEST="${ASSETS_DIR}/wallpaper.${ext}"

    msg "Installing wallpaper into the shared SDDM assets directory..."
    cp -f -- "$WALLPAPER" "$DEST" || die "Failed to copy wallpaper (missing permission?)"
    chmod 0644 "$DEST" || die "Failed to set permissions on $DEST"

    # Verify the greeter user can read it (root-only check)
    if [ "$(id -u)" -eq 0 ] && id sddm >/dev/null 2>&1 && command -v runuser >/dev/null 2>&1; then
        if runuser -u sddm -- test -r "$DEST" 2>/dev/null; then
            ok "Verified the SDDM greeter can read $DEST."
        else
            warn "SDDM greeter may not be able to read $DEST. Check parent dir permissions (must be at least a+rx)."
        fi
    fi

    # ---- Point Pixie at the synced wallpaper ----
    set_key "$THEME_CONF" "wallpaper" "$DEST"
    ok "theme.conf updated: Pixie wallpaper -> $DEST"

    # ---- Matugen palette ----
    if [ "${PIXIE_DISABLE_MATUGEN:-0}" = "1" ]; then
        msg "Matugen palette generation disabled (PIXIE_DISABLE_MATUGEN)."
    else
        msg "Generating the Material You palette with Matugen ($MODE)..."
        local FRAG
        FRAG="$(generate_palette "$DEST")" || FRAG=""
        if [ -n "$FRAG" ]; then
            commit_palette "$FRAG" "$THEME_CONF"
            ok "Matugen palette applied:"
            printf "      accent  : %s\n" "$(get_key "$THEME_CONF" matugenAccent)"
            printf "      surface : %s\n" "$(get_key "$THEME_CONF" matugenBackground)"
            printf "      text    : %s\n" "$(get_key "$THEME_CONF" matugenText)"
        else
            warn "Wallpaper synced, but the palette was left unchanged."
        fi
    fi

    # ---- Record state ----
    printf '%s\n' "$WALLPAPER" > "$ASSETS_DIR/.last-wallpaper" || true
    printf '%s\n' "$WALLSHA"  > "$ASSETS_DIR/.last-sha" || true
    chmod 0644 "$ASSETS_DIR"/.last-* 2>/dev/null || true

    echo ""
    ok "Wallpaper synchronization complete."
    echo "  The new wallpaper and colors are used the next time the greeter is shown."
    echo "  Preview :  sddm-greeter-qt6 --test-mode --theme $THEME_DIR   (Qt6)"
    echo "             sddm-greeter --test-mode --theme $THEME_DIR       (Qt5)"
}

main "$@"
